from pathlib import Path

def insert_before_sources(path, block):
    p=Path(path); text=p.read_text(encoding='utf-8')
    markers=['\n## 五、公开来源','\n## 六、公开来源','\n## 七、公开来源']
    for marker in markers:
        if marker in text:
            if block.strip() not in text:
                text=text.replace(marker,'\n'+block.strip()+'\n'+marker,1)
            break
    p.write_text(text.rstrip()+"\n", encoding='utf-8')

common={
'02-连锁药店/补充资料/连锁药店医保能力对比.md': '''## 四、业务应用分析\n\n### 1. 医保能力会改变药店在平台上的排序逻辑\n\n如果平台只按距离和价格排序，容易把能送药的门店排在前面；但医保场景下，定点资格、医保结算、处方承接和慢病服务会成为更重要的筛选条件。对用户来说，能不能医保支付有时比是否最快送达更关键。\n\n### 2. 线上医保能力不是线下定点资格的自动延伸\n\n线下医保定点说明门店具备医保服务基础，但线上医保还需要系统接口、实名核验、订单留痕、配送记录和地方政策支持。平台和药店如果把线下定点直接宣传成线上可支付，会高估实际能力。\n\n### 3. 慢病复购需要医保、处方和药师一起看\n\n慢病用户关注的不只是价格，还有长期处方、用药连续性和药师提醒。药店医保能力越强，越适合承接慢病复购，但前提是它能把医保结算、处方管理和药师服务做成稳定流程。\n''',
'02-连锁药店/补充资料/连锁药店合规处罚与监管风险案例.md': '''## 四、业务应用分析\n\n### 1. 合规风险会直接影响平台合作门槛\n\n平台接入药店时，不能只看品牌、门店数和距离。医保基金违规、处方药销售不规范、药师不在岗、追溯不完整都会影响平台责任。风险越高的门店，越需要限制品类、限制医保支付或强化审核。\n\n### 2. 处罚案例的价值在于形成风控清单\n\n单个处罚不能代表整个连锁品牌，但可以提醒平台在入驻审核中增加检查项，例如医保定点状态、历史处罚、药师配置、处方审核记录、库存追溯和投诉处理。\n\n### 3. 药企选择O2O渠道也要看药店合规\n\n药企如果把品牌药、处方药或慢病药放入O2O渠道，需要确认合作药店能否合规销售、正确储存和处理售后。否则平台曝光可能转化为品牌风险。\n''',
'07-政策与监管库/补充资料/医保基金监管政策摘要.md': '''## 四、业务应用分析\n\n### 1. 医保基金监管会改变线上买药的增长方式\n\n线上医保支付能提升用户转化，但也要求平台和药店证明每笔交易真实、合理、可追溯。增长不能只靠补贴和便利，还要保证身份、药品、处方、支付和配送记录一致。\n\n### 2. 基金监管会提高药店数字化要求\n\n定点药店需要保存处方、购销、支付和结算数据。线上场景下，药店还要把订单、配送和售后信息纳入可审计链路。没有数字化能力的药店，即使线下合规，也很难规模化承接线上医保。\n\n### 3. 平台要把反欺诈能力嵌入交易流程\n\n平台若承接医保支付，需要识别冒名购药、异常高频购买、串换药品和虚假交易。风控不应只在事后审核，而应嵌入用户认证、药品选择、支付和履约环节。\n''',
'07-政策与监管库/补充资料/医保目录调整与创新药目录政策摘要.md': '''## 四、业务应用分析\n\n### 1. 目录准入提升支付可及，但不等于渠道可及\n\n药品进入医保目录或商业健康保险创新药品目录，说明支付侧有机会改善，但患者是否能在线买到，还取决于处方、定点药店、DTP渠道、库存和配送条件。\n\n### 2. 创新药更适合用DTP和患者服务逻辑分析\n\n创新药通常不是普通即时配送场景。它更依赖医生处方、支付审核、患者教育、冷链或专业药房服务。平台若要参与创新药院外承接，需要证明的不只是入口，而是处方和患者服务能力。\n\n### 3. 药企应把目录变化转化为渠道策略\n\n目录调整后，药企需要判断哪些城市、哪些定点药店、哪些DTP渠道能承接支付变化。平台曝光只是一部分，更关键的是药店端能否完成处方、医保和患者服务。\n''',
'07-政策与监管库/补充资料/国家医保局政策文件索引_2025-2026.md': '''## 四、业务应用分析\n\n### 1. 政策索引的价值是建立跟踪地图\n\n国家医保局文件很多，不能把所有文件都当成买药机会。索引应帮助读者判断哪些文件影响基金监管，哪些影响目录支付，哪些影响定点药店，哪些影响线上医保和慢病统筹。\n\n### 2. 2025-2026年应重点跟踪支付和监管两条线\n\n对平台买药来说，支付线决定线上医保和慢病复购能否扩展，监管线决定基金安全、定点协议和数据留痕要求是否提高。二者共同决定平台是否能把买药从OTC扩展到处方和慢病。\n\n### 3. 索引不能停留在链接列表\n\n每个政策文件进入信息库后，都应标注影响主体、影响流程、可证明事项和后续需要补的业务数据。否则索引只能查资料，不能支持业务判断。\n''',
'07-政策与监管库/补充资料/处方流转与互联网诊疗监管细则.md': '''## 四、业务应用分析\n\n### 1. 处方流转决定平台能否承接处方药\n\n处方药线上销售的核心不是配送，而是处方从哪里来、谁审核、如何留痕。平台如果无法证明处方来源和审方链路，就只能安全地做OTC和非处方场景，不能直接扩展到处方药。\n\n### 2. 互联网诊疗是处方链路的上游能力\n\n互联网诊疗规则决定哪些患者可以在线复诊、哪些医生可以开方、哪些病历和处方需要留存。平台买药如果依赖互联网医院，就必须把医疗服务资质和药品销售资质分开核验。\n\n### 3. 药店的价值从“卖药”转向“审方和服务”\n\n处方流转让药店承担更多审核和用药服务责任。药店越能稳定完成审方、调配、药师咨询和处方留痕，越适合承接处方药O2O。\n''',
'07-政策与监管库/补充资料/定点零售药店监管政策.md': '''## 四、业务应用分析\n\n### 1. 定点资格是医保购药入口，不是全部能力\n\n药店成为医保定点，只说明它具备参与医保服务的基础资格。线上场景还要看系统接口、处方、结算、配送和数据上传。平台选择药店时，不能把“定点”当成唯一判断。\n\n### 2. 协议管理会影响药店与平台合作边界\n\n医保经办机构与药店的服务协议约定了费用结算、服务质量和违规责任。药店接入平台后，如果订单、配送或宣传方式影响协议要求，可能带来基金和协议风险。\n\n### 3. 定点药店监管会推动平台做门店级管理\n\n平台不能只管理连锁总部，还需要识别每家门店的定点状态、服务范围、结算能力和风险记录。门店级能力越透明，平台买药越容易扩展到医保和慢病场景。\n''',
'07-政策与监管库/补充资料/平台补贴价格竞争与反不正当竞争监管.md': '''## 四、业务应用分析\n\n### 1. 补贴可以带来订单，也可能损害药店服务质量\n\n低价和补贴能提高转化，但如果压缩药店毛利，药店可能减少药师服务、库存深度或售后投入。医药场景里，价格竞争不能脱离质量和服务。\n\n### 2. 药品促销比普通商品更受限制\n\n药品涉及功效表达、处方药展示、赠药促销和广告审查。平台活动页不能只按快消品逻辑设计，药企和药店也不能用夸大疗效或不合规赠送获取流量。\n\n### 3. 价格监管会影响平台长期竞争方式\n\n如果平台买药长期依赖补贴，很难证明复购和服务质量。更可持续的竞争方式应是医保支付、稳定库存、药师服务、慢病管理和履约稳定性。\n''',
'07-政策与监管库/补充资料/慢特病与门诊统筹政策资料.md': '''## 四、业务应用分析\n\n### 1. 慢特病和门诊统筹会把买药从即时需求变成长期服务\n\n急用药更强调速度，慢特病更强调连续用药、医保支付、处方续配和药师服务。平台如果要承接慢病复购，不能只优化配送，而要组织长期服务链路。\n\n### 2. 定点药店是慢病院外承接的重要节点\n\n部分地区门诊统筹和慢病用药可以通过定点零售药店承接。药店是否具备医保结算、处方管理和慢病服务，会直接影响平台能否获得高频复购场景。\n\n### 3. 药企需要按病种和支付政策设计渠道\n\n慢病药企不能只看平台流量，应关注哪些城市允许药店承接、哪些病种可支付、哪些药店有患者服务能力。渠道策略要和地方政策、医保支付和药店能力结合。\n''',
'07-政策与监管库/补充资料/线上医保支付与定点零售药店政策.md': '''## 四、业务应用分析\n\n### 1. 线上医保支付是地方系统工程\n\n线上医保买药不是平台单方能力，而是地方医保系统、定点药店、平台入口、实名支付和基金风控共同实现。不同城市路径不同，平台不能用单地经验直接外推。\n\n### 2. 定点药店决定交易能否落地\n\n即使平台有流量，最终结算主体和履约主体仍通常落在定点药店。药店是否接入线上医保、是否有库存、是否能审方和配送，决定用户能否完成订单。\n\n### 3. 费用拆分影响用户体验和合规展示\n\n线上医保购药常常需要区分药品费、配送费、包装费和平台服务费。平台若展示不清，用户会误解“医保支付”的范围，也可能引发投诉和合规风险。\n''',
'07-政策与监管库/补充资料/药品召回与不良反应监管资料.md': '''## 四、业务应用分析\n\n### 1. 即时零售会放大召回和通知能力的重要性\n\n线上买药把订单分散到多个门店和用户地址，一旦发生召回，平台和药店需要快速定位订单、批次、用户和配送记录。没有追溯和交易留痕，召回效率会下降。\n\n### 2. 不良反应反馈可以成为药品服务闭环的一部分\n\n平台买药不能只在交付后结束。用户用药后的不良反应、投诉和咨询，应该能回到药店、药师和药企的安全监测链路。\n\n### 3. 药企需要关注O2O渠道的售后协同\n\n药企进入平台和药店O2O渠道后，需要确认平台能否下架、通知、追溯、协助召回和处理不良反应线索。渠道越分散，协同越重要。\n''',
'07-政策与监管库/补充资料/药品流通追溯与一物一码政策.md': '''## 四、业务应用分析\n\n### 1. 一物一码让线上药品交易更可审计\n\n如果订单能够关联药品追溯码、药店库存、用户签收和医保支付，平台买药就更容易支持基金监管、召回和质量追溯。没有这一层数据，平台只能证明订单发生，不能证明药品链路完整。\n\n### 2. 追溯能力会区分药店供给质量\n\n两家药店都能送药，但追溯、购销记录和库存管理能力不同，合规风险也不同。平台筛选药店时，应把追溯能力纳入供给质量指标。\n\n### 3. 药企可以用追溯数据管理院外渠道\n\n药企通过追溯和渠道数据，可以更好判断产品在O2O药店的流向、召回效率和异常风险。即时零售不是简单增加销售渠道，而是增加一条需要数据治理的流通链路。\n'''
}
for p,b in common.items(): insert_before_sources(p,b)
print('more analysis inserted',len(common))
